#include <stdint.h>
#include <stdbool.h>

typedef struct {
    uint8_t data[64];
    uint8_t head;
    uint8_t tail;
} circular_buffer_t;

bool buffer_push(circular_buffer_t *buf, uint8_t value) {
    uint8_t next_head = (buf->head + 1) % 64;
    if (next_head == buf->tail) {
        return false;
    }
    buf->data[buf->head] = value;
    buf->head = next_head;
    return true;
}

bool buffer_pop(circular_buffer_t *buf, uint8_t *value) {
    if (buf->head == buf->tail) {
        return false;
    }
    *value = buf->data[buf->tail];
    buf->tail = (buf->tail + 1) % 64;
    return true;
}

int main(void) {
    circular_buffer_t buf = {0};
    for (int i = 0; i < 100; i++) {
        buffer_push(&buf, i);
    }
    return 0;
}
